declare
  n public.needs; p public.app_profiles; pref public.worker_match_preferences;
  hard text[] := '{}'; disp text[] := '{}'; reasons text[] := '{}';
  tz text; local_day date;
  svc boolean; toolsok boolean; vehok boolean; expok boolean;
  sched boolean; dist numeric; radiusok boolean; feeok boolean;
  effective_radius numeric; exposure integer;
  cap numeric := 0; ss numeric := 0; ds numeric := 0; rs numeric := 0;
  rels numeric := 0; fair numeric := 0;
begin
  select * into n from public.needs where id = nid;
  if not found then
    return jsonb_build_object('responseAllowed',false,'dispatchEligible',false,
      'hardBlockers',jsonb_build_array('NEED_NOT_FOUND'));
  end if;
  select * into p from public.app_profiles where id = pid and kind = 'WORKER';
  if not found then
    return jsonb_build_object('responseAllowed',false,'dispatchEligible',false,
      'hardBlockers',jsonb_build_array('WORKER_PROFILE_NOT_FOUND'));
  end if;
  select * into pref from public.worker_match_preferences where worker_profile_id = pid;

  tz := coalesce(nullif(pref.timezone,''), 'Europe/Belgrade');
  local_day := case when n.starts_at is not null then (n.starts_at at time zone tz)::date end;

  svc := cardinality(n.required_skills) = 0
         or private.lower_arr(p.skills) && private.lower_arr(n.required_skills)
         -- PKG-031b (deep read 9.3): the same kind of work in other words ("Ciscenje stana" / "čišćenje stana").
         or private.work_kinds_v5(p.skills) && private.work_kinds_v5(n.required_skills);
  toolsok := private.lower_arr(p.tools) @> private.lower_arr(n.required_tools);
  -- WPP01: licenses no longer participate in admission or resource ranking.
  vehok := private.lower_arr(p.vehicles) @> private.lower_arr(n.required_vehicles);
  expok := coalesce(n.minimum_experience_years,0) = 0
           or coalesce(p.years_experience,0) >= n.minimum_experience_years;
  sched := private.worker_dispatch_time_admitted(nid,pid);
  effective_radius := private.effective_radius_km(p.radius_km);

  if n.execution_location_mode = 'REMOTE' then
    dist := null; radiusok := true;
  else
    dist := private.haversine_km(n.approximate_lat, n.approximate_lng,
                                 pref.approximate_lat, pref.approximate_lng);
    radiusok := case
      when dist is not null then dist <= effective_radius
      else btrim(coalesce(n.approximate_city,'')) <> ''
           and lower(coalesce(n.approximate_city,'')) = lower(coalesce(p.city,''))
    end;
  end if;

  feeok := n.mode = 'OFFERS'
           or coalesce(p.minimum_fee_rsd,0) = 0
           or (n.requester_price_rsd is not null and n.requester_price_rsd >= p.minimum_fee_rsd);

  -- TVRDE kapije: blokiraju i rucni odgovor, ne samo automatski dispatch.
  if p.profile_status <> 'ACTIVE' then hard := array_append(hard,'ACCOUNT_OR_PROFILE_RESTRICTED'); end if;
  if n.requester_account_id = p.account_id then hard := array_append(hard,'OWN_NEED'); end if;
  if n.verified_identity_required and not private.identity_admitted(p.account_id)
    then hard := array_append(hard,'IDENTITY_VERIFICATION_NOT_ADMITTED'); end if;
  if not toolsok then hard := array_append(hard,'MISSING_REQUIRED_TOOL'); end if;
  if not vehok  then hard := array_append(hard,'MISSING_REQUIRED_VEHICLE'); end if;
  if not expok  then hard := array_append(hard,'INSUFFICIENT_EXPERIENCE'); end if;
  if private.lower_arr(p.exclusions) && private.lower_arr(array_prepend(n.category, n.required_skills))
     -- PKG-031b (deep read 9.2/9.3): an exclusion holds for the same kind of work in any spelling
     -- ("selidbe" also keeps out "transport_selidbe").
     or private.work_kinds_v5(p.exclusions) && private.work_kinds_v5(array_prepend(n.category, n.required_skills))
    then hard := array_append(hard,'PROFILE_EXCLUSION'); end if;

  -- MEKE kapije: blokiraju samo automatsku isporuku. Rucno pretrazivanje ostaje otvoreno.
  if not coalesce(p.available_now,false)
    -- EX-06 ex06a: a TOMORROW_FLEXIBLE / WEEK_FLEXIBLE task stored without a window and published is matched against the window private.worker_dispatch_time_admitted derives for it,
    -- so it is future availability here too (W02: live intent off but a real weekly schedule is not paused for a future task). Live intent alone is still no availability.
    and not (private.availability_is_future(n.schedule_kind,n.starts_at,n.ends_at,statement_timestamp())
             or (n.starts_at is null and n.ends_at is null and n.published_at is not null
                 and n.schedule_kind in ('TOMORROW_FLEXIBLE','WEEK_FLEXIBLE')))
    then disp := array_append(disp,'CURRENT_AVAILABILITY_PAUSED'); end if;
  if not coalesce(pref.proactive_notifications,true) then disp := array_append(disp,'PROACTIVE_NOTIFICATIONS_PAUSED'); end if;
  if n.urgent
     and (n.schedule_kind = 'TODAY_FLEXIBLE'
          or (n.starts_at is not null and (n.starts_at at time zone tz)::date = (statement_timestamp() at time zone tz)::date))
     and not coalesce(pref.same_day_urgent_notifications,true)
    then disp := array_append(disp,'SAME_DAY_URGENT_NOTIFICATIONS_PAUSED'); end if;
  if not svc then disp := array_append(disp,'SERVICE_NOT_IN_WORK_PROFILE'); end if;
  if not sched then disp := array_append(disp,'OUTSIDE_AVAILABILITY'); end if;
  if not radiusok then disp := array_append(disp,'OUTSIDE_PREFERRED_RADIUS'); end if;
  if not feeok then disp := array_append(disp,'BELOW_MINIMUM_FEE'); end if;

  -- Bodovanje: donorove tezine 30/25/15/15/10/5.
  if svc then reasons := array_append(reasons,'SERVICE_MATCH'); cap := 30; end if;
  if sched then reasons := array_append(reasons,'SCHEDULE_MATCH'); ss := 25; end if;
  if radiusok then
    reasons := array_append(reasons, case when n.execution_location_mode='REMOTE'
                 then 'REMOTE_LOCATION_NOT_REQUIRED' else 'START_PROXIMITY_MATCH' end);
    ds := case
      when n.execution_location_mode='REMOTE' then 15
      when dist is null or effective_radius is null or effective_radius <= 0 then 10
      else round(15 * (1 - 0.55 * least(1, greatest(0, dist/effective_radius))), 1)
    end;
  end if;
  if toolsok and vehok then reasons := array_append(reasons,'RESOURCES_MATCH'); rs := 15; end if;

  rels := round(greatest(0, least(100, coalesce(p.rating_worker*20, 50)))/10, 1);
  select count(*) into exposure from public.opportunity_deliveries d
   where d.worker_account_id = p.account_id
     and d.created_at > statement_timestamp() - interval '7 days';
  fair := case when p.rating_worker is null then 5 else greatest(0, 5 - least(5, exposure)) end;
  if p.rating_worker is null then reasons := array_append(reasons,'NEWCOMER_FAIRNESS'); end if;

  return jsonb_build_object(
    'workerAccountId', p.account_id,
    'workerProfileId', p.id,
    'responseAllowed', cardinality(hard) = 0,
    'dispatchEligible', cardinality(hard) = 0 and cardinality(disp) = 0,
    'hardBlockers', to_jsonb(hard),
    'dispatchBlockers', to_jsonb(disp),
    'reasonCodes', to_jsonb(reasons),
    'distanceToStartKm', dist,
    'effectiveRadiusKm', effective_radius,
    'taskLocationMode', n.execution_location_mode,
    'distanceSource', case when dist is null then null else 'GEODESIC' end,
    'routingProvider', null,
    'liveStateDate', local_day,
    'score', round(least(100, cap+ss+ds+rs+rels+fair), 1),
    'scoreComponents', jsonb_build_object(
      'capability', cap, 'schedule', ss, 'distanceToStart', ds,
      'resources', rs, 'reliability', rels, 'fairness', fair)
  );
end;
$mv1_body$),
  ('private.dispatch_cheap_candidate_admitted(uuid,uuid)','563792537e89d451416f053205fdcace','e51de37e0883fcd3cd4e6e3c42fb6ee1',$mv1_body$
  select exists (
    select 1
    from public.needs n
    join public.app_profiles p on p.id = pid
    left join public.worker_match_preferences pref on pref.worker_profile_id = p.id
    where n.id = nid
      and p.kind = 'WORKER'
      and p.profile_status = 'ACTIVE'
      and private.worker_dispatch_time_admitted(nid,pid)
      and p.account_id <> n.requester_account_id
      and private.accounts_same_world(n.requester_account_id, p.account_id)
      and coalesce(pref.proactive_notifications, true) = true
      and (not n.verified_identity_required or private.identity_admitted(p.account_id))
      and (cardinality(n.required_skills) = 0
           or private.lower_arr(p.skills) && private.lower_arr(n.required_skills)
           or private.work_kinds_v5(p.skills) && private.work_kinds_v5(n.required_skills))
      -- WPP01: licenses are retired from task eligibility; historical arrays remain stored.
      and private.lower_arr(p.tools) @> private.lower_arr(n.required_tools)
      and private.lower_arr(p.vehicles) @> private.lower_arr(n.required_vehicles)
      and (coalesce(n.minimum_experience_years,0) = 0
           or coalesce(p.years_experience,0) >= n.minimum_experience_years)
      and not (private.lower_arr(p.exclusions)
               && private.lower_arr(array_prepend(n.category, n.required_skills))
               or private.work_kinds_v5(p.exclusions)
               && private.work_kinds_v5(array_prepend(n.category, n.required_skills)))
      and (n.mode = 'OFFERS' or coalesce(p.minimum_fee_rsd,0) = 0
           or (n.requester_price_rsd is not null and n.requester_price_rsd >= p.minimum_fee_rsd))
      and not exists (
        select 1 from public.opportunity_deliveries od
        where od.worker_account_id = p.account_id
          and od.need_id = n.id
          and od.need_revision = n.revision)
  );
$mv1_body$),
  ('private.worker_dispatch_time_admitted(uuid,uuid)','a58f1d1a2d21fa057867c153ae62ba4e','4f0beb65922d2b3d947d69e68a56a956',$mv1_body$
declare n public.needs; p public.app_profiles; tz text; wtz text; at_now timestamptz:=statement_timestamp(); periods tstzmultirange;
  ws timestamptz; we timestamptz; anchor_day date;
begin
  select * into n from public.needs where id=nid;
  if not found then return false; end if;
  select * into p from public.app_profiles where id=pid and kind='WORKER' and profile_status='ACTIVE';
  if not found then return false; end if;
  select timezone into tz from public.worker_match_preferences where worker_profile_id=pid;
  tz:=coalesce(tz,'Europe/Belgrade');
  if not private.availability_timezone_valid(tz) then return false; end if;
  -- EX-06 ex06a (S03 finding F1). A TOMORROW_FLEXIBLE or WEEK_FLEXIBLE task stored WITHOUT a window used to be refused for every worker (availability_is_future is false without one).
  -- It is now matched against the window its own words mean, derived in the task's timezone (Europe/Belgrade when the task has none or an invalid one, never the worker's):
  -- sutra = the local calendar day after the publication day; ove nedelje = the publication day to the end of that local Monday-Sunday week (the existing rule below clips the start to now,
  -- so it is the remaining part of the week). The anchor is published_at (as private.relative_schedule_end_v5 does), so a later wave does not move "tomorrow"; a task without published_at
  -- keeps the refusal. The rule that follows is the existing one: some real available time inside the window, never the whole day or week. A stored window (or one endpoint) and every other
  -- schedule kind are exactly as before.
  ws:=n.starts_at; we:=n.ends_at;
  if n.starts_at is null and n.ends_at is null and n.schedule_kind in ('TOMORROW_FLEXIBLE','WEEK_FLEXIBLE') then
    if n.published_at is null then return false; end if;
    wtz:=case when n.task_timezone is not null and private.availability_timezone_valid(n.task_timezone) then n.task_timezone else 'Europe/Belgrade' end;
    anchor_day:=(n.published_at at time zone wtz)::date;
    if n.schedule_kind='TOMORROW_FLEXIBLE' then
      ws:=(anchor_day+1)::timestamp at time zone wtz; we:=(anchor_day+2)::timestamp at time zone wtz;
    else
      ws:=anchor_day::timestamp at time zone wtz; we:=(anchor_day+(8-extract(isodow from anchor_day)::integer))::timestamp at time zone wtz;
    end if;
  end if;
  if private.availability_is_future(n.schedule_kind,ws,we,at_now) then
    periods:=private.worker_available_periods(pid,greatest(ws,at_now),we,tz);
    if n.schedule_kind='FIXED_WINDOW' then return periods @> tstzrange(ws,we,'[)'); end if;
    -- A flexible search window needs some real available time, not the whole
    -- day/week. It never reserves this window or invents an estimated duration.
    return periods<>'{}'::tstzmultirange;
  end if;
  if n.schedule_kind in ('TOMORROW_FLEXIBLE','WEEK_FLEXIBLE') or
    (n.ends_at is not null and n.ends_at<=at_now) then return false; end if;
  if not p.available_now then return false; end if;
  if exists(select 1 from public.profile_availability_windows w where w.profile_id=pid
    and w.availability_state='UNAVAILABLE' and w.starts_at<=at_now and w.ends_at>at_now)
    or exists(select 1 from private.worker_calendar_events c where c.worker_profile_id=pid
      and c.state='BLOCKING' and c.starts_at<=at_now and c.ends_at>at_now) then return false; end if;
  if n.schedule_kind='FIXED_WINDOW' then return private.schedule_fit(pid,n.starts_at,n.ends_at,tz); end if;
  return true;
end;
$mv1_body$),
  ('private.dispatch_next_wave(uuid)','cafdef0ff95b5dc6467f4fa1db3dafc0','2b58d69640ac802a5dd3fa3cef6c56d0',$mv1_body$
declare
  n public.needs;
  cfg jsonb; sizes jsonb; budget jsonb; urgcfg jsonb;
  roundno integer; policy_wave_no integer;
  batch integer; target integer; windowm integer; min_choice integer;
  candidate_limit integer; budget_source text;
  active integer; active_coverage integer; selected integer; remaining integer;
  roundid uuid := gen_random_uuid();
  inserted integer := 0;
  c record; d jsonb; deadline timestamptz; urg text;
begin
  select * into n from public.needs where id = nid for update;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;

  if n.status not in ('PUBLISHED','SELECTION') then
    return jsonb_build_object('status','STOPPED','reason','NEED_NOT_OPEN','inserted',0);
  end if;

  if n.remaining_search_closed_at is not null then
    return jsonb_build_object('status','STOPPED','reason','REMAINING_SEARCH_CLOSED','inserted',0);
  end if;

  if not private.need_search_time_admitted_v1(n.id, clock_timestamp()) then
    return jsonb_build_object('status','STOPPED','reason','SEARCH_WINDOW_CLOSED','inserted',0);
  end if;

  select coalesce(sum(covered_slots),0) into selected
    from public.need_selections where need_id = nid and status = 'SELECTED';
  remaining := greatest(0, n.required_slots - selected);
  if remaining = 0 then
    return jsonb_build_object('status','STOPPED','reason','SLOTS_FILLED','inserted',0,
      'selectedSlots',selected,'remainingSlots',0);
  end if;

  select count(*), coalesce(sum(covered_slots),0) into active, active_coverage
    from public.marketplace_responses
   where need_id = nid and submitted_against_need_revision = n.revision
     and status in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED');

  -- Hitnost se cita iz projekcije, ne iz sirove zastavice: istekao prozor je NORMAL.
  urg := case when coalesce(n.urgent,false) and n.urgent_expires_at > statement_timestamp()
              then 'URGENT' else 'NORMAL' end;

  select value into cfg from private.marketplace_config
   where key = case when urg = 'URGENT' then 'dispatch_urgent' else 'dispatch_normal' end;
  if cfg is null then raise exception using errcode='55000', message='DISPATCH_CONFIG_MISSING'; end if;

  sizes := cfg->'waveSizes';
  target := (cfg->>'targetResponses')::integer;
  windowm := (cfg->>'windowMinutes')::integer;
  if jsonb_typeof(sizes) <> 'array' or jsonb_array_length(sizes) = 0
     or target is null or target < 1 or windowm is null or windowm < 1 then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;

  if active >= target and active_coverage >= remaining then
    return jsonb_build_object('status','STOPPED','reason','RESPONSE_TARGET_AND_COVERAGE_REACHED',
      'inserted',0,'activeResponses',active,'activeCoverage',active_coverage,
      'selectedSlots',selected,'remainingSlots',remaining);
  end if;

  budget := private.candidate_budget(urg = 'URGENT', greatest(0, remaining - active_coverage), cfg);
  candidate_limit := (budget->>'limit')::integer;
  budget_source := budget->>'source';
  if candidate_limit is null or candidate_limit < 1 or candidate_limit > 10000 then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;

  select coalesce(max(round_no),0)+1 into roundno
    from public.dispatch_rounds where need_id = nid and need_revision = n.revision;
  select count(*)+1 into policy_wave_no
    from public.dispatch_rounds
   where need_id = nid and need_revision = n.revision and urgency = urg
     -- PKG-027a: a check that found nobody reached nobody, so it does not use up a wave.
     and not (status = 'STOPPED' and stop_reason = 'NO_ELIGIBLE_CANDIDATES');

  if policy_wave_no > jsonb_array_length(sizes) then
    return jsonb_build_object('status','STOPPED','reason','WAVES_EXHAUSTED','inserted',0,
      'activeResponses',active,'activeCoverage',active_coverage,
      'selectedSlots',selected,'remainingSlots',remaining,'candidateLimit',candidate_limit);
  end if;

  batch := (sizes->>(policy_wave_no-1))::integer;

  -- O-3: pod izbora za HITNO.
  if urg = 'URGENT' then
    select value into urgcfg from private.marketplace_config where key = 'urgent_activation_policy';
    min_choice := coalesce(nullif(urgcfg->>'minChoice','')::integer, 2);
    if min_choice < 2 or min_choice > 10 then min_choice := 2; end if;
    batch := greatest(batch, min_choice);
  end if;

  deadline := statement_timestamp() + make_interval(mins => windowm);

  insert into public.dispatch_rounds(id,need_id,need_revision,round_no,urgency,batch_size,
      target_responses,candidate_limit_used,budget_source,status,deadline_at)
    values (roundid,n.id,n.revision,roundno,urg,batch,target,candidate_limit,budget_source,'SENT',deadline);

  for c in
    with candidate_base as materialized (
      select p.id as pid, p.account_id as uid, pc.candidate_rank
      from private.candidate_profile_ids(n.id, candidate_limit)
           with ordinality as pc(worker_profile_id, candidate_rank)
      join public.app_profiles p on p.id = pc.worker_profile_id
      order by pc.candidate_rank
    ), scored as materialized (
      select b.pid, b.uid, private.match_detail(n.id, b.pid) as detail from candidate_base b
    )
    select s.pid, s.uid, s.detail from scored s
    where coalesce((s.detail->>'dispatchEligible')::boolean, false)
    order by (s.detail->>'score')::numeric desc, s.pid
  loop
    exit when inserted >= batch;
    d := c.detail;
    insert into public.opportunity_deliveries(worker_account_id,worker_profile_id,need_id,
        need_revision,dispatch_round_id,match_score,score_components,reason_codes,status,expires_at)
      values (c.uid,c.pid,n.id,n.revision,roundid,(d->>'score')::numeric,
        coalesce(d->'scoreComponents','{}'::jsonb) || jsonb_build_object(
          'distanceToStartKm', d->'distanceToStartKm',
          'effectiveRadiusKm', d->'effectiveRadiusKm',
          'distanceSource', d->'distanceSource',
          'taskLocationMode', d->'taskLocationMode'),
        array(select jsonb_array_elements_text(d->'reasonCodes')), 'READY', deadline)
      on conflict do nothing;

    if found then
      inserted := inserted + 1;
      perform private.emit_event(
        p_recipient => c.uid, p_role => 'WORKER',
        p_event_type => 'OPPORTUNITY_AVAILABLE',
        p_entity_type => 'NEED', p_entity_id => n.id, p_entity_version => n.revision,
        p_title => 'Nova prilika koja može da Vam odgovara',
        p_body => left(n.title,140),
        p_dedupe_key => 'opp:'||n.id::text||':'||n.revision::text||':'||c.uid::text,
        p_urgency => case when urg = 'URGENT' then 'HITNO' else 'NORMAL' end,
        p_payload => jsonb_build_object('needRevision',n.revision,
                       'reasonCodes',d->'reasonCodes','remainingSlots',remaining),
        p_expires_at => deadline);
    end if;
  end loop;

  if inserted = 0 then
    update public.dispatch_rounds
       set status = 'STOPPED', stop_reason = 'NO_ELIGIBLE_CANDIDATES'
     where id = roundid;
  end if;

  return jsonb_build_object(
    'status', case when inserted > 0 then 'SENT' else 'STOPPED' end,
    'round', roundno, 'policyWaveNo', policy_wave_no, 'urgency', urg,
    'inserted', inserted, 'batchSize', batch, 'minChoice', min_choice,
    'deadlineAt', deadline,
    'activeResponses', active, 'activeCoverage', active_coverage,
    'selectedSlots', selected, 'remainingSlots', remaining,
    'candidateLimit', candidate_limit, 'budgetSource', budget_source,
    'routingCallsUsed', 0, 'routingProvider', null,
    'candidateRetrieval', 'CLEAN_STREAMING_BOUNDED_GEO_KNN',
    'authoritative', true);
end;
$mv1_body$),
  ('private.dispatch_tick(integer,timestamp with time zone)','947783612b6bea3170cdbc6dd657e6fd','8798cb6b6f004ecd5d88dd472cd6de0b',$mv1_body$
declare
  claimed uuid[]; r record; candidate record; res jsonb;
  processed integer := 0; sent integer := 0; stopped integer := 0; failed integer := 0;
  reason text; next_at timestamptz;
begin
  if p_batch is null or p_batch < 1 or p_batch > 200 then p_batch := 25; end if;

  -- Claim each free Need and queue in a bounded successful-claim batch.
  -- locked_until je zastita od procesa koji padne usred obrade.
  -- Each attempt locks its Need before its queue. A skipped queue rolls back
  -- this small subtransaction, releasing that unsuccessful Need lock. Thus a
  -- queue-only holder cannot starve the next free item or accumulate held Needs.
  claimed := '{}'::uuid[];
  for candidate in
    select s.need_id from private.dispatch_schedule s
    where s.next_run_at <= p_at
      and (s.locked_until is null or s.locked_until < p_at)
    order by s.next_run_at, s.need_id
  loop
    begin
      perform 1 from public.needs n where n.id = candidate.need_id
        for update of n skip locked;
      if not found then continue; end if;
      perform 1 from private.dispatch_schedule s
        where s.need_id = candidate.need_id and s.next_run_at <= p_at
          and (s.locked_until is null or s.locked_until < p_at)
        for update of s skip locked;
      if not found then
        raise exception using errcode = 'UD108', message = 'DISPATCH_QUEUE_SKIPPED';
      end if;
      update private.dispatch_schedule s
        set locked_until = p_at + interval '2 minutes', updated_at = statement_timestamp()
        where s.need_id = candidate.need_id;
      claimed := array_append(claimed, candidate.need_id);
    exception when sqlstate 'UD108' then
      null;
    end;
    exit when cardinality(claimed) >= p_batch;
  end loop;

  for r in select unnest(claimed) as need_id loop
    processed := processed + 1;
    begin
      res := private.dispatch_next_wave(r.need_id);
      reason := coalesce(res->>'reason', res->>'status');

      if (res->>'status') = 'SENT' then
        sent := sent + 1;
        -- Sledeci talas tek kad se prozor ovog zatvori.
        next_at := coalesce((res->>'deadlineAt')::timestamptz, p_at + interval '15 minutes');
        update private.dispatch_schedule
           set next_run_at = next_at, locked_until = null, attempts = 0,
               last_status = 'SENT', last_reason = null, updated_at = statement_timestamp()
         where need_id = r.need_id;

      elsif reason in ('SLOTS_FILLED','NEED_NOT_OPEN','WAVES_EXHAUSTED',
                       'RESPONSE_TARGET_AND_COVERAGE_REACHED','REMAINING_SEARCH_CLOSED',
                       'SEARCH_WINDOW_CLOSED') then
        stopped := stopped + 1;
        delete from private.dispatch_schedule where need_id = r.need_id;

      else
        -- NO_ELIGIBLE_CANDIDATES i slicno: eksponencijalno odlaganje do sest sati, bez odustajanja
        -- (PKG-027a). Promena kod radnika vraca zadatak u red odmah (requeue_open_needs_for_worker_v5).
        stopped := stopped + 1;
        update private.dispatch_schedule
           set attempts = attempts + 1,
               locked_until = null,
               next_run_at = p_at + make_interval(
                 mins => least(360, greatest(5, (2 ^ least(attempts, 9))::integer))),
               last_status = 'STOPPED', last_reason = reason,
               updated_at = statement_timestamp()
         where need_id = r.need_id;
      end if;

    exception when others then
      failed := failed + 1;
      update private.dispatch_schedule
         set attempts = attempts + 1, locked_until = null,
             next_run_at = p_at + interval '10 minutes',
             last_status = 'ERROR', last_reason = left(sqlerrm, 200),
             updated_at = statement_timestamp()
       where need_id = r.need_id;
    end;
  end loop;

  return jsonb_build_object('processed',processed,'sent',sent,'stopped',stopped,
                            'failed',failed,'batch',p_batch,'claimed',cardinality(claimed));
end;
$mv1_body$)) patches(signature,before_md5,after_md5,new_body) loop
  o:=to_regprocedure(r.signature);
  if o is null then raise exception 'MATCH_V1_REVERT_MISSING_FUNCTION: %',r.signature using errcode='55000'; end if;
  select p.prosrc,to_jsonb(p)-'prosrc',obj_description(p.oid,'pg_proc') into strict body,meta,comment_before from pg_proc p where p.oid=o;
  if md5(body) is distinct from r.before_md5 then raise exception 'MATCH_V1_REVERT_PREIMAGE_DRIFT: %',r.signature using errcode='55000'; end if;
  if md5(r.new_body) is distinct from r.after_md5 then raise exception 'MATCH_V1_REVERT_PAYLOAD_DRIFT: %',r.signature using errcode='55000'; end if;
  def:=pg_get_functiondef(o);
  if (length(def)-length(replace(def,body,'')))/length(body)<>1 then raise exception 'MATCH_V1_REVERT_BODY_ANCHOR_DRIFT: %',r.signature using errcode='55000'; end if;
  execute replace(def,body,r.new_body);
  if (select p.prosrc from pg_proc p where p.oid=o) is distinct from r.new_body
   or (select to_jsonb(p)-'prosrc' from pg_proc p where p.oid=o) is distinct from meta
   or obj_description(o,'pg_proc') is distinct from comment_before
  then raise exception 'MATCH_V1_REVERT_POSTIMAGE_OR_METADATA_DRIFT: %',r.signature using errcode='55000'; end if;
 end loop;
end
$match_v1_revert_replace$;
drop function private.worker_need_match_v1(uuid,uuid);
drop function private.worker_need_fit_v1(uuid,uuid);
drop function private.requeue_changed_worker_profiles_v1(timestamp with time zone);
drop function private.worker_need_time_tier_v1(uuid,uuid);
delete from private.marketplace_config where key='match_v1_profile_requeue';
do $match_v1_revert_post$
declare r record;
begin
 for r in select * from (values
  ('private.match_detail_without_calendar(uuid,uuid)','ef5de901069c1a8cfa729cfb6bbadde9'),
  ('private.dispatch_cheap_candidate_admitted(uuid,uuid)','e51de37e0883fcd3cd4e6e3c42fb6ee1'),
  ('private.worker_dispatch_time_admitted(uuid,uuid)','4f0beb65922d2b3d947d69e68a56a956'),
  ('private.dispatch_next_wave(uuid)','2b58d69640ac802a5dd3fa3cef6c56d0'),
  ('private.dispatch_tick(integer,timestamp with time zone)','8798cb6b6f004ecd5d88dd472cd6de0b')) pins(signature,body_md5) loop
  if (select md5(p.prosrc) from pg_proc p where p.oid=to_regprocedure(r.signature)) is distinct from r.body_md5
  then raise exception 'MATCH_V1_REVERT_POSTIMAGE_DRIFT: %',r.signature using errcode='55000'; end if;
 end loop;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private')
   and p.proname in ('worker_need_time_tier_v1','worker_need_fit_v1','worker_need_match_v1','requeue_changed_worker_profiles_v1'))
  or exists(select 1 from private.marketplace_config where key='match_v1_profile_requeue')
 then raise exception 'MATCH_V1_REVERT_INCOMPLETE' using errcode='55000'; end if;
 if private.closure_source_digest_v5() is distinct from (select digest from match_v1_certificate)
  or private.closure_erasure_program_digest_v5() is distinct from (select program from match_v1_certificate)
 then raise exception 'MATCH_V1_REVERT_CERTIFICATE_MOVED' using errcode='55000'; end if;
 if private.closure_source_digest_v5() is null or private.closure_erasure_program_digest_v5() is null
  or private.closure_source_digest_v5() is distinct from (select sha256 from private.closure_source_v5 where singleton)
  or private.closure_source_digest_v5() is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton)
  or private.retention_ai_source_ready() is distinct from true
 then raise exception 'MATCH_V1_REVERT_CERTIFICATE_NOT_READY_AFTER' using errcode='55000'; end if;
end
$match_v1_revert_post$;
